// 失败输出实际领域错误，断言不能把无关缺夹具问题误称为被测拒绝。
void must(Status result){if(!result.ok){std::cerr<<result.error.original.code<<" "<<result.error.original.path<<"\n";std::abort();}}
template<class T> T must(Outcome<T> result){if(!result.ok){std::cerr<<result.error.original.code<<" "<<result.error.original.path<<"\n";std::abort();}return std::move(result.value);}
